using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests
{
 public sealed class ChallengeTests
 {
  void OpenMenuRoute(string route){game.GetComponent<IdleIntelligence.Runtime.GameMenu>().Open();Assert.That(GameObject.Find("MainMenu").GetComponentsInChildren<Button>().Count(b=>b.name=="Menu-"+route),Is.EqualTo(1));Click("Menu-"+route);}


  string dir;GameRuntime game;
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-challenge-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  static Button Button(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);return b;}
  static void Click(string name){var b=Button(name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  void FinanceAndUnlock(){Debug.Log("FUNDED_CHALLENGE_UI_STATE: temporary test save, not a natural run");game.Act(s=>{var n=s.Copy();n.Credits=n.Data=ScientificNumber.From(1e12);n.Prestige.resets=1;n.Tutorial="done";n.Industry.discovered=Enumerable.Repeat(true,Balance.Hardware.Length).ToArray();for(int i=0;i<n.Research.Length;i++)n.Research[i]=Balance.Research[i].Project?1:4;n.Workshop.nodes=new[]{"F01","F04","F08"};n.Prestige.known=(string[])n.Workshop.nodes.Clone();n.Workshop.inventory=new[]{new ItemInstance{id="funded-loadout",type="quantum-chip",level=9,rarity=2,forge=1,locked=true}};n=Workshop.Equip(n,"funded-loadout","processor");n=Game.Buy(n,"sbc");n=Game.Buy(n,"pc");n=Game.Train(n,"quality");n=Game.Research(n,"modelArchitecture");return n;});}
  [UnityTest]public IEnumerator FailedSaveKeepsOriginalAndRollsBackUncommittedChallengeSwitch(){FinanceAndUnlock();Click("ResearchTab");yield return null;OpenMenuRoute("challenges");yield return null;string original="externally damaged original must be preserved";File.WriteAllText(game.SavePath,original);LogAssert.Expect(LogType.Warning,new System.Text.RegularExpressions.Regex("Speichern gesperrt"));Click("StartChallenge");Assert.That(game.Writable,Is.False);Assert.That(ChallengeRules.Active(game.State),Is.False,"Uncommitted switch rolled back");Assert.That(File.ReadAllText(game.SavePath),Is.EqualTo(original));Assert.That(Button("StartChallenge").interactable,Is.False);}
  [UnityTest]public IEnumerator StartAndAbortPreserveMainJobsAndSaveBeforeNavigation()
  {FinanceAndUnlock();Click("ResearchTab");yield return new WaitForSecondsRealtime(.35f);Assert.That(game.Content.Cast<Transform>().Count(t=>t.name=="ChallengesAccess"&&t.gameObject.activeInHierarchy),Is.Zero,"Refresh must not duplicate navigation");OpenMenuRoute("challenges");yield return null;Assert.That(game.Content.Cast<Transform>().Count(t=>t.name=="ChallengesAccess"&&t.gameObject.activeInHierarchy),Is.Zero,"Navigation cleared on entering challenge view");Click("StartChallenge");Assert.That(ChallengeRules.Active(game.State),Is.True);Assert.That(game.State.Hardware[0],Is.EqualTo(1),"Actual paid no-taps starter");Assert.That(game.TapButton.interactable,Is.False);var main=game.State.Challenges.Main.Copy();Assert.That(main.Training,Is.Not.Null);Assert.That(main.ResearchJob,Is.Not.Null);var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Challenges.Run,Is.Not.Null,"Saved before tab switch");Click("ResearchTab");yield return null;OpenMenuRoute("challenges");yield return null;Assert.That(GameObject.Find("ChallengeStatus").GetComponent<Text>().text,Does.Contain("pausiert"));Click("AbortChallenge");Assert.That(ChallengeRules.Active(game.State),Is.False);Assert.That(game.State.Credits.CompareTo(main.Credits),Is.Zero);Assert.That(game.State.Workshop.inventory[0].id,Is.EqualTo("funded-loadout"));Assert.That(game.State.Workshop.inventory[0].level,Is.EqualTo(9));Assert.That(game.State.Training.done,Is.EqualTo(main.Training.done));Assert.That(game.State.ResearchJob.done,Is.EqualTo(main.ResearchJob.done));yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(ChallengeRules.Active(game.State),Is.False);Assert.That(game.State.Challenges.Progress.lastSuccess,Is.False);}
  [UnityTest]public IEnumerator PreparedCompletionPersistsOnceEvenIfOldButtonFiresAgain()
  {FinanceAndUnlock();Click("ResearchTab");yield return null;OpenMenuRoute("challenges");yield return null;Click("StartChallenge");game.Act(s=>{var n=s.Copy();n.Challenges.Run.metrics.credits=ChallengeRules.Current(n).Goals.First(g=>g.Id=="passive-credits").Target.ToData();return n;});Click("ResearchTab");yield return null;OpenMenuRoute("challenges");yield return null;var old=Button("CompleteChallenge");old.onClick.Invoke();Assert.That(game.State.Challenges.Progress.stars,Is.EqualTo(2));Assert.That(game.State.Challenges.Progress.completions[0],Is.EqualTo(1));old.onClick.Invoke();Assert.That(game.State.Challenges.Progress.stars,Is.EqualTo(2));var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True);Assert.That(loaded.State.Challenges.Progress.stars,Is.EqualTo(2));Assert.That(loaded.State.Challenges.Run,Is.Null);}
  [UnityTest]public IEnumerator SerialRulesLinksSelectionAndMobilePresentationUseRealControls()
  {FinanceAndUnlock();Click("ResearchTab");yield return null;OpenMenuRoute("challenges");yield return null;for(int i=0;i<9;i++)Click("ChallengeFamily");Assert.That(GameObject.Find("ChallengeLink-sbc"),Is.Not.Null);Click("ChallengeLink-sbc");Assert.That(Button("StartChallenge").interactable,Is.True,"Four of five defaults still satisfy chapter one");WorkshopTests.Capture(320,568,"/tmp/unity-challenge-funded-320.png");WorkshopTests.Capture(390,844,"/tmp/unity-challenge-funded-390.png");WorkshopTests.Capture(430,932,"/tmp/unity-challenge-funded-430.png");Click("ChallengeFamily");for(int i=0;i<7;i++)Click("ChallengeFamily");for(int i=0;i<10;i++)Click("NextChallengeStage");Assert.That(Button("StartChallenge").interactable,Is.False,"Stage 11 needs prior stage ownership");game.Act(s=>{var n=s.Copy();n.Challenges.Progress.stages[7]=10;return n;});Click("PreviousChallengeStage");Click("NextUnfinishedChallenge");Click("StartChallenge");Assert.That(game.State.Challenges.Run.id,Is.EqualTo("serial-science"));Assert.That(PrestigeAutomation.LabCount(game.State),Is.EqualTo(1));game.Act(s=>{var n=s.Copy();n.Data=n.Credits=ScientificNumber.From(1e12);return n;});Click("ResearchTab");yield return null;GameObject.Find("research-dataGeneration").GetComponent<LearningCard>().StartAction.onClick.Invoke();Assert.That(game.State.ResearchJob.id,Is.EqualTo("dataGeneration"));Assert.That(GameObject.Find("research-syntheticData").GetComponent<LearningCard>().StartAction.interactable,Is.False,"Area alternation enforced in UI");var before=game.State.Data;game.SetResearchArea(Workshop.ResearchArea("modelArchitecture"));GameObject.Find("research-modelArchitecture").GetComponent<LearningCard>().StartAction.onClick.Invoke();Assert.That(game.State.Prestige.researchQueue,Is.EqualTo(new[]{"modelArchitecture"}));Assert.That(game.State.Data.CompareTo(before),Is.Zero,"Queue is unpaid");var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.State.Challenges.Run.id,Is.EqualTo("serial-science"));Assert.That(loaded.State.Challenges.Main.Training,Is.Not.Null);}
 }
}
